private synchronized void goShopping(int amount) { ... }  // 锁 this=ryan 或 monica
// ryan 锁 ryan，monica 锁 monica，互不干扰 → 照样透支

// 正确修法 A：同步块锁住共享账户
synchronized (account) { if (account.getBalance()>=amount) account.spend(amount); }

// 正确修法 B（更好）：谁拥有数据谁保护 —— 把逻辑封进 BankAccount
public synchronized void spend(String name, int amount) {   // 锁 this=共享账户
  if (balance >= amount) { balance -= amount; ... }          // 检查+扣款一次做完
}
