public class LostUpdate {
  public static void main(String[] args) throws InterruptedException {
    ExecutorService pool = Executors.newFixedThreadPool(6);
    Balance balance = new Balance();
    for (int i = 0; i < 1000; i++) pool.execute(() -> balance.increment());
    pool.shutdown();
    if (pool.awaitTermination(1, TimeUnit.MINUTES))  // 等所有任务跑完再打印
      System.out.println("balance = " + balance.balance); // 理论 1000，实际常小于 1000
  }
